 230	\begin{definition}[Win predicate of the classical low individual degree game]\label{def:ld-win-predicate}
 231		\uses{def:ld-game, def:ld-question-distribution, def:line, def:polyfunc}
 232		Fix $\mathsf{ldparams} = (q,m,d,k)$. Answers in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
 233		\begin{itemize}
 234			\item Type $\mathsf{Point}$, question content $u \in \F_q^m$: the answer is an element of $\F_q^k$.
 235			\item Type $\mathsf{ALine}$, question content $(u_0,s) \in \F_q^m \times \F_q$, specifying the axis-parallel line $\ell(u_0,e_i)$ with $i = \chi(s)$: the answer is a $k$-tuple $(f_1,\ldots,f_k)$ of univariate polynomials $f_j\colon \F_q \to \F_q$ of degree at most $d$, each given by its $d+1$ coefficients.
 236			\item Type $\mathsf{DLine}$, question content $(u_0,s,v) \in \F_q^m \times \F_q \times \F_q^m$, specifying the diagonal line $\ell(u_0,v')$ with $v' = \pi_{i-1}(v)$ and $i = \chi(s)$: the answer is a $k$-tuple of univariate polynomials of degree at most $md$.
 237		\end{itemize}
 238		The win predicate $D^{\mathrm{ld}} = D^{\mathrm{ld}}_{\mathsf{ldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A,\mathrm B\}$; in all cases where no action is indicated, the predicate accepts.
 239		\begin{enumerate}
 240			\item (\textbf{Consistency test}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
 241			% The source phrases both clauses with "the" t such that x = u_0 + tv; that phrase
 242			% does not determine t on diagonal questions with direction v' = 0, which the
 243			% question distribution samples with positive probability. The universal
 244			% quantification over t used here is the local correction; see the remark below.
 245			\item (\textbf{Axis-parallel line-versus-point test}) If $t_w = \mathsf{ALine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t e_i$, where $i = \chi(s)$.
 246			\item (\textbf{Diagonal line-versus-point test}) If $t_w = \mathsf{DLine}$ and $t_{\overline w} = \mathsf{Point}$, accept if and only if $f_j(t) = (a_{\overline w})_j$ for all $j \in \{1,2,\ldots,k\}$ and all $t \in \F_q$ such that $x_{\overline w} = u_0 + t v'$, where $v' = \pi_{i-1}(v)$ and $i = \chi(s)$.
 247		\end{enumerate}
