 599	\begin{theorem}[Projectivity of the combined strategy]
 600		\label{thm:ld-combined-strategy-projective}
 601		\lean{MIPStarRE.QPBT.directCombinedStrategy_isProjective}
 602		\leanok
 603		\uses{def:ld-combined-strategy, def:projective-strategy-general}
 604		For every strategy $\mathcal S$ for the directly indexed low-degree game, if
 605		$\mathcal S$ is projective, then the combined strategy
 606		$\mathcal S^{\mathrm c}$ is projective.
 607	\end{theorem}
 608	\begin{proof}
 609		\leanok
 610		\uses{def:ld-combined-strategy, lem:sandwich-postprocess-projective}
 611		For either player and every question of the combined game, the corresponding
 612		measurement of $\mathcal S^{\mathrm c}$ is obtained by relabelling the outcomes
 613		of one measurement of $\mathcal S$.  Every such post-processing of a
 614		projective measurement is projective.
 615	\end{proof}
