2385	\begin{lemma}[Soundness bound for the canonical parameters]\label{lem:delta-bound}
2386		\lean{MIPStarRE.QPBT.introParamsTuple_isAdmissible, MIPStarRE.QPBT.le_two_pow_introParams_m, MIPStarRE.QPBT.exists_deltaQld_introParams_bound}
2387		\leanok
2388		\uses{def:introparams, def:admissible, thm:pauli}
2389		For all integers $R \ge 4$, the parameter tuple $\mathsf{introparams}(R) = (q,m,d)$ is admissible (Definition~\ref{def:admissible}) and satisfies $2^m \ge R$. Furthermore, there exist universal constants $a' \ge 1$ and $0 < b' \le 1$ such that, for every $\eps \ge 0$, the function $\delta_{\mathrm{qld}}(\eps, m, d, q)$ of Theorem~\ref{thm:pauli} is at most
2390		\[
2391			a' \bigl( (\log R)^{a'} \cdot \eps^{b'} + (\log R)^{-b'} \bigr)\;.
2392		\]
2393	\end{lemma}
2394	\begin{proof}
2395		\leanok
2396		\uses{def:introparams, def:admissible, def:admissible-size, thm:pauli, lem:delta-bound-envelope-support}
2397		Since $c$ is even, the exponent $k = c \lceil \log\log R \rceil + 1$ is odd, so $q = 2^k$ is an admissible field size; $m$ divides $q$ because $2^j \le c \lceil \log R \rceil + 1 \le 2 \log^c R \le 2^k$, so $j \le k$ and both are powers of $2$; and $d = 1 \ge 1$. Hence the tuple is admissible. Since $m = 2^j \ge (c/2) \log R$, we get $2^m \ge R^{c/2} \ge R$, using $c \ge 2$.
2398	
2399		For the soundness bound, write $\delta_{\mathrm{qld}}(\eps,m,d,q) = a(md)^a \eps^b + a(md)^a q^{-b} + a(md)^a 2^{-bmd}$ and use $d = 1$, $\log R \le m \le 2c \log R$, and $q = 2^k \ge \log^c R$. Set
2400		\[
2401			C = \frac{\lceil a + b \rceil !}{(b \ln 2)^{\lceil a + b \rceil}}
2402			\qquad \text{and} \qquad
2403			a' = a\bigl( (2c)^a + C \bigr)\;,
2404		\]
2405		both depending only on the universal constants $a$ and $b$; since $a \ge 1$, $c \ge 2$ and $C \ge 0$, one has $a' \ge a \ge 1$. The first term is at most $a(2c)^a (\log R)^a \eps^b \le a' (\log R)^{a'} \eps^b$, using $\log R \ge 2 \ge 1$ and $a \le a'$. The second term is at most $a(2c)^a (\log R)^{a - cb} \le a(2c)^a (\log R)^{-b}$, since $cb - a \ge b$ by the choice of $c$. For the third term, split $m^a = m^{a+b} \cdot m^{-b}$ and bound the first factor against the exponential: for all real $s$, all $t > 0$ and all $x \ge 1$, the Taylor estimate $y^n / n! \le e^y$ of the exponential, taken at $y = (t \ln 2) x$ and $n = \lceil s \rceil_{+} = \max(\lceil s \rceil, 0)$, gives
2406		\[
2407			x^s\, 2^{-tx} \le \frac{\lceil s \rceil_{+}!}{(t \ln 2)^{\lceil s \rceil_{+}}}\;.
2408		\]
2409		With $s = a + b$, $t = b$ and $x = m$ the right-hand side is the constant $C$ above, so
2410		\[
2411			a(md)^a\, 2^{-bm}
2412			= a \bigl( m^{a+b}\, 2^{-bm} \bigr) m^{-b}
2413			\le a\, C\, m^{-b}
2414			\le a\, C\, (\log R)^{-b}\;,
2415		\]
2416		the last step using $m \ge \log R \ge 1$. Summing the three bounds, the statement follows with $a'$ as above and $b' = b$.
2417	\end{proof}
